"""Shared helpers for the probes: per-group verdicts for any set of arms, plus kernel builders.

Everything here goes through gate.py's own machinery (same cases, same oracles), so a
probe's numbers are the gate's numbers.
"""

from __future__ import annotations

import importlib.util
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

import numpy as np  # noqa: E402

import gate  # noqa: E402
from autokernel_pbt.props.oracle import DeclarativeOracle, ReferenceOracle, summary  # noqa: E402
from autokernel_pbt.props.verdict import Verdict  # noqa: E402

RESULTS = ROOT / "results"
RESULTS.mkdir(exist_ok=True)

EPS32 = float(np.finfo(np.float32).eps)


def load_kernel(path: Path):
    return gate.load_kernel(path)


def old_bundle() -> DeclarativeOracle:
    return gate.declarative(include_laws=False)


def completed_bundle() -> DeclarativeOracle:
    return gate.declarative(include_laws=True)


def with_extra_laws(case_laws=(), group_laws=()) -> DeclarativeOracle:
    """The OLD bundle plus the given laws (used to score alternative completions)."""
    base = old_bundle()
    return DeclarativeOracle(
        [*base.case_properties, *case_laws], [*base.group_properties, *group_laws]
    )


def per_group(kernel, arms: dict[str, object]) -> dict[str, dict[str, tuple[str, str]]]:
    """arm -> group_id -> (verdict, first failing detail). Mirrors gate.check per group."""
    by_group = gate.rows_by_group(kernel)
    out: dict[str, dict[str, tuple[str, str]]] = {}
    for name, arm in arms.items():
        out[name] = {}
        for gid, rows in by_group.items():
            results = arm.evaluate(rows)
            verdict = summary(results)
            detail = ""
            if verdict is Verdict.FAIL:
                bad = next(r for r in results if r.verdict is Verdict.FAIL)
                detail = f"{bad.property_name}: {bad.detail}"
            out[name][gid] = (str(verdict), detail)
    return out


def failed(groups: dict[str, tuple[str, str]]) -> int:
    return sum(1 for v, _ in groups.values() if v == "fail")


def group_shapes() -> dict[str, tuple[int, ...]]:
    by_group = gate.rows_by_group(gate.reference())
    return {gid: tuple(rows[0].case.shape) for gid, rows in by_group.items()}


def standard_arms() -> dict[str, object]:
    return {
        "old_bundle": old_bundle(),
        "completed_bundle": completed_bundle(),
        "reference": ReferenceOracle(gate.reference()),
    }


def to_sphere(w, dtype):
    """Project rows onto S_n = {y : sum y = 0, |y|^2 = n}; zero rows -> 0."""
    w = np.asarray(w, dtype=np.float64)
    z = w - w.mean(axis=-1, keepdims=True)
    norm = np.sqrt(np.sum(z * z, axis=-1, keepdims=True))
    safe = np.where(norm > 0, norm, 1.0)
    return np.where(norm > 0, z * (np.sqrt(z.shape[-1]) / safe), 0.0).astype(dtype)


def center(x):
    w = np.asarray(x, dtype=np.float64)
    return w - w.mean(axis=-1, keepdims=True)


def helmert(n):
    q = np.zeros((n, n - 1))
    for k in range(1, n):
        q[:k, k - 1] = 1.0
        q[k, k - 1] = -k
        q[:, k - 1] /= np.sqrt(k * (k + 1))
    return q


def rotation_kernel(theta: float):
    """Reference rotated by theta inside the zero-mean hyperplane (identity for n < 3)."""

    def layernorm(x):
        z = center(x)
        n = z.shape[-1]
        if n < 3:
            return to_sphere(z, x.dtype)
        q = helmert(n)
        g = np.eye(n - 1)
        c, s = np.cos(theta), np.sin(theta)
        g[0, 0], g[0, 1], g[1, 0], g[1, 1] = c, -s, s, c
        rot = q @ g @ q.T + np.ones((n, n)) / n
        return to_sphere(z @ rot.T, x.dtype)

    return layernorm


def eps_kernel(eps: float, outside: bool = False):
    """The reference with a different eps, inside (default) or outside the square root."""

    def layernorm(x):
        w = np.asarray(x, dtype=np.float64)
        mean = np.mean(w, axis=-1, keepdims=True)
        zc = w - mean
        var = np.mean(zc * zc, axis=-1, keepdims=True)
        denom = np.sqrt(var) + eps if outside else np.sqrt(var + eps)
        if eps == 0.0 and not outside:
            denom = np.where(denom > 0, denom, 1.0)
        return (zc / denom).astype(x.dtype)

    return layernorm


def md_table(headers: list[str], rows: list[list[str]]) -> str:
    out = ["| " + " | ".join(headers) + " |", "|" + "|".join("---" for _ in headers) + "|"]
    out += ["| " + " | ".join(str(c) for c in r) + " |" for r in rows]
    return "\n".join(out)

=== run_all.py ===
"""Gate every kernel in admitted/, correct_variants/ and probes/kernels/ and check the claims.

Three arms per kernel, all through gate.py's machinery: the OLD bundle (bundle.yaml as
is), the COMPLETED bundle (old + laws.py) and the reference arm. Writes
results/summary.md and results/summary.json; exits 1 if any expectation is violated.

Expectations (RESULT.md):
  admitted/*          old 0/9, completed > 0, reference > 0, and completed fails EXACTLY
                      the groups the reference fails (arm agreement)
  correct_variants/*  all three arms 0/9
  probes/kernels/*    individual, see EXPECT below
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

import numpy as np

sys.path.insert(0, str(Path(__file__).resolve().parent))
from _harness import (  # noqa: E402
    EPS32,
    RESULTS,
    ROOT,
    failed,
    group_shapes,
    load_kernel,
    md_table,
    per_group,
    standard_arms,
)

sys.path.insert(0, str(ROOT))
import gate  # noqa: E402
import laws  # noqa: E402
from autokernel_pbt.props.tolerance import residual_ratio  # noqa: E402

ZERO, POS = "0", ">0"
EXPECT = {
    "admitted": {"old_bundle": ZERO, "completed_bundle": POS, "reference": POS, "agree": True},
    "correct_variants": {"old_bundle": ZERO, "completed_bundle": ZERO, "reference": ZERO},
    "probes/kernels/eps_free_normalizer": {"old_bundle": ZERO, "completed_bundle": ZERO, "reference": ZERO},
    "probes/kernels/eps_outside_sqrt": {"old_bundle": ZERO, "completed_bundle": ZERO, "reference": ZERO},
    "probes/kernels/onepass_float32": {"completed_bundle": POS, "reference": POS, "agree": True},
    "probes/kernels/anisotropy_witness": {"old_bundle": ZERO, "completed_bundle": ZERO, "reference": POS},
    "probes/kernels/hash_rotation": {"old_bundle": POS, "reference": POS},
    "probes/kernels/radial_scale_1e-4": {"completed_bundle": POS, "reference": POS, "agree": False},
}


def expectation_for(rel: str) -> dict:
    if rel in EXPECT:
        return EXPECT[rel]
    return EXPECT[rel.split("/")[0]]


def new_law_margin(kernel) -> tuple[float, float]:
    """Max test ratio of the direction law and min fitted scale over all 18 cases."""
    worst, min_a = 0.0, float("inf")
    for rows in gate.rows_by_group(kernel).values():
        for r in rows:
            x, y = r.case.tensors["x"], r.outputs["y"]
            a, b, fit, zz = laws.affine_fit(x, y)
            worst = max(worst, residual_ratio(y.astype(np.float64), fit, dtype=y.dtype, n=y.shape[-1]))
            if np.any(zz > 0):
                min_a = min(min_a, float(np.min(a[zz > 0])))
    return worst, min_a


def main() -> int:
    arms = standard_arms()
    shapes = group_shapes()
    files = sorted(
        [*(ROOT / "admitted").glob("*.py"), *(ROOT / "correct_variants").glob("*.py"),
         *(ROOT / "probes" / "kernels").glob("*.py")]
    )
    files.insert(0, ROOT / "reference.py")
    rows, record, violations = [], {}, []
    for path in files:
        rel = str(path.relative_to(ROOT).with_suffix(""))
        kernel = load_kernel(path)
        verdicts = per_group(kernel, arms)
        counts = {arm: failed(g) for arm, g in verdicts.items()}
        comp_fail = {gid for gid, (v, _) in verdicts["completed_bundle"].items() if v == "fail"}
        ref_fail = {gid for gid, (v, _) in verdicts["reference"].items() if v == "fail"}
        disagree = sorted(comp_fail ^ ref_fail)
        margin, min_a = new_law_margin(kernel)
        exp = {"old_bundle": ZERO, "completed_bundle": ZERO, "reference": ZERO} if rel == "reference" else expectation_for(rel)
        ok = True
        for arm, want in exp.items():
            if arm == "agree":
                if want and disagree:
                    ok = False
                if not want and not disagree:
                    ok = False
                continue
            got = counts[arm]
            if (want == ZERO and got != 0) or (want == POS and got == 0):
                ok = False
        if not ok:
            violations.append(rel)
        first = next((d for v, d in verdicts["completed_bundle"].values() if v == "fail"), "")
        record[rel] = {
            "groups_failed": counts,
            "disagreeing_groups": [f"{g}{shapes[g]}" for g in disagree],
            "direction_law_max_ratio": margin,
            "direction_law_min_scale": min_a,
            "first_completed_failure": first,
            "expectation_met": ok,
        }
        rows.append([
            rel, f"{counts['old_bundle']}/9", f"{counts['completed_bundle']}/9", f"{counts['reference']}/9",
            ", ".join(str(shapes[g]) for g in disagree) or "none",
            f"{margin:.2g}", "OK" if ok else "VIOLATED",
        ])
        print(f"{rel:45s} old={counts['old_bundle']} completed={counts['completed_bundle']} "
              f"ref={counts['reference']} disagree={len(disagree)} law_ratio_max={margin:.3g} {'OK' if ok else 'VIOLATED'}")

    table = md_table(
        ["kernel", "old bundle (groups failed)", "completed bundle", "reference arm",
         "groups where completed and reference disagree", "direction-law max ratio (thresh 30)", "expectation"],
        rows,
    )
    (RESULTS / "summary.md").write_text(
        "# Gate results for every kernel in this directory\n\n"
        f"numpy {np.__version__}, float32 eps = {EPS32:.3g}, seed 42, 9 groups x 2 cases. "
        "Produced by probes/run_all.py.\n\n" + table + "\n"
    )
    (RESULTS / "summary.json").write_text(json.dumps(record, indent=2))
    print(f"\nwrote {RESULTS / 'summary.md'}; violations: {violations or 'none'}")
    return 1 if violations else 0


if __name__ == "__main__":
    raise SystemExit(main())

